'use strict';
// The reference screenshot's dark surfaces, restrained accent, and direct hierarchy.
paths.home='m3 10 9-8 9 8 M5 9v12h5v-7h4v7h5V9';
paths.books='M3 4h4v16H3z M9 3h4v17H9z M15 5l4-1 4 16-4 1z';
paths.settings='M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8';
navs.forEach(n=>{if(n[0]==='today'){n[1]='home';n[2]='首页';}if(n[0]==='library'){n[1]='books';n[2]='资料库';}if(n[0]==='settings')n[2]='设置';});
brainLayout='list';
function homeTabs(){return `<nav class="workspace-tabs" aria-label="首页内容切换">${[['today','收藏',state.brain.items.filter(x=>!x.deleted).length],['opportunities','机会',actionable().length],['digest','精选',digests.length]].map(([v,t,n])=>`<button class="workspace-tab ${page===v?'active':''}" data-action="navigate" data-page="${v}" aria-current="${page===v?'page':'false'}">${t}<small>${n}</small></button>`).join('')}</nav>`;}
header=function(eye,title,subtitle,actions=''){
  const count=state.brain.items.filter(x=>!x.deleted).length;
  const titles={today:'Sift',opportunities:'机会雷达',digest:'每日精选',library:showTrash?'最近删除':selectedCollection?state.brain.collections.find(c=>c.id===selectedCollection)?.name:'资料库',watch:'稍后看',settings:'设置',sources:'信息来源','campus-saved':'校园收藏'};
  const subtitles={today:`${count} 条收藏 · 本地演示`,opportunities:`${actionable().length} 条待关注 · 模拟群消息`,digest:'3 条示例精选 · 尚未接入自动生成',library:showTrash?'删除的内容可以在这里恢复。':'按收藏集整理文章、笔记与图片。',watch:`${state.brain.items.filter(x=>x.watch&&!x.deleted).length} 条待阅读 · 不发送后台通知`,settings:'关注方向、提醒偏好与本地数据。',sources:'选择演示来源，真实账号尚未接入。','campus-saved':'已收藏的校园机会与精选。'};
  return `<div class="page-heading"><div><h1>${esc(titles[page]||title)}</h1><p class="page-subtitle">${esc(subtitles[page]||subtitle)}</p></div><div class="heading-buttons">${actions}</div></div>${['today','opportunities','digest'].includes(page)?homeTabs():''}`;
};
art=function(item){return item.image?`<img class="cover-art" src="${esc(item.image)}" alt="${esc(item.title)}的本地图片">`:'';};
contentCard=function(item){return `<article class="content-card ${item.image?'has-image':''}">${item.image?`<button style="display:block;width:100%;padding:0" data-action="content-detail" data-id="${item.id}" aria-label="打开图片：${esc(item.title)}"><img class="content-thumbnail" src="${esc(item.image)}" alt="${esc(item.title)}" loading="lazy"></button>`:''}<div class="content-card-body"><div class="content-card-category">${icon({tech:'spark',study:'flask',life:'sun',travel:'pin',book:'book'}[item.category]||'book')}${B.categories[item.category]||'未分类'}<span class="content-chip-status">${item.status==='sample'?'示例':item.status==='link-only'?'未抓取正文':item.status==='image-only'?'未识别文字':'笔记'}</span></div><button class="content-title" data-action="content-detail" data-id="${item.id}">${esc(item.title)}</button><p class="content-summary">${esc(item.summary)}</p><div class="content-tags">${item.tags.slice(0,3).map(t=>`<button class="content-tag inline-tag-button" data-action="content-tag" data-value="${esc(t)}"># ${esc(t)}</button>`).join('')}</div><div class="content-card-footer"><span class="content-status">${icon(item.image?'image':item.url?'link':'book')} ${esc(item.platform)}</span><div class="content-actions">${item.deleted?`<button data-action="content-restore" data-id="${item.id}" aria-label="恢复${esc(item.title)}">${icon('rotate')}</button>`:`<button data-action="content-watch" data-id="${item.id}" class="${item.watch?'on':''}" aria-label="${item.watch?'移出稍后看':'加入稍后看'}：${esc(item.title)}" aria-pressed="${!!item.watch}">${icon('clock')}</button><button data-action="content-collection" data-id="${item.id}" aria-label="管理${esc(item.title)}的收藏集">${icon('folder')}</button><button data-action="content-detail" data-id="${item.id}" aria-label="阅读${esc(item.title)}">${icon('arrow')}</button>`}</div></div></div></article>`;};
contentResults=function(){const result=selectedContents();return `<div class="content-section-heading"><h2>${showTrash?'已删除的内容':selectedCollection?esc(state.brain.collections.find(c=>c.id===selectedCollection)?.name||'收藏集'):brainQuery?'搜索结果':page==='watch'?'待阅读':'全部收藏'} <span class="shelf-count">${result.length}</span></h2><select id="brain-sort" aria-label="收藏排序"><option value="new" ${brainSort==='new'?'selected':''}>最近保存</option><option value="title" ${brainSort==='title'?'selected':''}>按标题排序</option></select></div>${result.length?`<div class="content-grid ${brainLayout==='list'?'grid-list':''}">${result.map(contentCard).join('')}</div>`:`<div class="empty">${icon(showTrash?'trash':'source')}<h3>${showTrash?'没有已删除内容':brainQuery?'没有找到相关内容':'暂无内容'}</h3><p>${showTrash?'删除的收藏会暂存在这里。':brainQuery?'试试其他关键词或分类。':'添加链接、笔记或图片，建立你的资料库。'}</p>${showTrash?'':button('capture',icon('plus')+'添加内容','primary small')}</div>`}`;};
todayView=function(){showTrash=false;return header('','Sift','',button('capture',icon('plus')+'添加','primary'))+contentToolbar()+categoryChips()+`<section id="content-results">${contentResults()}</section>`;};
watchView=function(){showTrash=false;return header('','稍后看','',button('capture',icon('plus')+'添加','primary'))+contentToolbar()+categoryChips()+`<section id="content-results">${contentResults()}</section>`;};
libraryView=function(){const collection=state.brain.collections.find(c=>c.id===selectedCollection);return header('','资料库','',collection?button('rename-collection',icon('edit')+'重命名','',`data-id="${collection.id}"`)+button('remove-collection','移除','',`data-id="${collection.id}"`):button('capture',icon('plus')+'添加','primary')+button('new-collection','新建收藏集','small'))+`${!selectedCollection&&!showTrash?`<div class="collection-strip"><button class="collection-tile" data-action="navigate" data-page="watch">${icon('clock')}<strong>稍后看</strong><small>${state.brain.items.filter(x=>!x.deleted&&x.watch).length} 条内容</small></button>${state.brain.collections.map(c=>`<button class="collection-tile ${c.color}" data-action="open-collection" data-id="${c.id}">${icon('folder')}<strong>${esc(c.name)}</strong><small>${state.brain.items.filter(x=>!x.deleted&&x.collections.includes(c.id)).length} 条内容</small></button>`).join('')}</div>`:''}${selectedCollection||showTrash?'<button class="return-link" data-action="all-collections">← 全部收藏集</button>':''}${contentToolbar()}${categoryChips()}<section id="content-results">${contentResults()}</section>${!showTrash?`<div class="compact-library-tools"><button class="btn text" data-action="legacy-saved">校园收藏 (${state.items.filter(x=>x.saved).length+state.savedDigests.length})</button><button class="btn text" data-action="show-trash">最近删除</button><button class="btn text" data-action="export">导出数据</button></div>`:''}`;};
const modalBeforeMinimal=showModal;
showModal=function(html){const replacements=[['把这一刻的灵感，收进来。','添加内容'],['重新整理这条收藏。','编辑内容'],['给这个空间换个名字。','重命名收藏集'],['新的兴趣，新的小空间。','新建收藏集'],['这份灵感，放在哪里？','选择收藏集'],['让一条消息，变成一次机会。','模拟群消息'],['给重要的事，留个位置。','提醒计划'],['稍后，再提醒自己。','设置演示提醒'],['保存到我的大脑','保存内容'],['给这份灵感起个名字','输入标题'],['记下内容，也记下你为什么想留住它。','输入正文或补充说明'],['Sift，你的第二大脑。','关于Sift'],['预置示例；封面为原创示意插画，不代表真实视频或文章缩略图。','预置示例内容，不代表真实视频或文章分析结果。']];for(const [a,b]of replacements)html=html.split(a).join(b);modalBeforeMinimal(html);};
const renderBeforeMinimal=render;
render=function(){renderBeforeMinimal();if(['opportunities','digest','watch','campus-saved'].includes(page)){const active=page==='watch'||page==='campus-saved'?'library':'today';$(`#nav [data-page="${active}"]`)?.classList.add('active');}$('#floating-capture').setAttribute('aria-label','添加内容');};
const settingsBeforeMinimal=settingsView;
settingsView=function(){return settingsBeforeMinimal()+`<div class="digest-main"><section class="setting-box"><h3>信息来源</h3><p class="sub">管理模拟群和公众号来源。</p><div style="margin-top:15px">${button('navigate','管理信息来源','', 'data-page="sources"')}</div></section></div>`;};
render();
